Session.OpenModelRequestClosedBeforeLeav.source:
({ before, after, events }) => {
			if (
				before._tag !== "Running" ||
				before.open_model_request_id === null ||
				(after._tag === "Running" && after.turn === before.turn)
			) {
				return true
			}
			const endIndex = events.findIndex(
				(event) =>
					event._tag === "span.model_request_end" &&
					event.model_request_start_id === before.open_model_request_id,
			)
			const leaveIndex = events.findIndex(
				(event) =>
					event._tag === "session.status_idle" || event._tag === "session.status_terminated",
			)
			return endIndex >= 0 && (leaveIndex < 0 || endIndex < leaveIndex)
		}

AdmitSession.PinnedVersionWithinAgentHea.source:
({ before, command, events }) => {
			const pinned = command.agent_version ?? before.agent.version
			return (
				before.agent.version >= 1 &&
				pinned >= 1 &&
				pinned <= before.agent.version &&
				events.length === 1 &&
				events.every(
					(event) =>
						event.agent_id === command.agent_id &&
						event.agent_version === pinned &&
						event.environment_id === command.environment_id,
				)
			)
		}

Checkfu.EverySessionReferencesExistingAg.source:
