Checkfu.ReservedSlotsEqualLiveAutomation.source:
(m) => {
			const live = m.Automation.filter((a) =>
				[a.state.status === "active", a.state.status === "paused"].some((ok) => ok),
			).length
			return m.AutomationCapacity.length === 0
				? live === 0
				: m.AutomationCapacity.every((c) => c.state.reserved === live)
		}

Artifact.CreatingTakesTheOpenReservation.source:
({ before, after, command }) => {
			if (command._tag !== "CreateArtifact") {
				return true
			}
			return [
				after.status === before.status,
				[before.open_reservation !== 0, before.open_reservation === command.reservation].every(
					(ok) => ok,
				),
			].some((ok) => ok)
		}
